// Resize family executor: host helpers plus the device-side resize entry
// points (nppiResize, nppiResizeSqrPixel, nppiResizeBatch).
//
// The public wrappers are generated by mpp_scripts/gen_family.py
// (mpp_scripts/families/nppi_resize*.json).
//
// Host helper semantics (baseline NVIDIA NPP 13.4 on RTX 5090, measured with
// standalone probes; goldens in test/unit/diff/test_nppi_resize_host_generated.cpp):
//
// nppiGetResizeRect(oSrcROI, pDstRect, nXFactor, nYFactor, nXShift, nYShift,
//                   eInterpolation):
//   * validation order: pDstRect == NULL -> NPP_NULL_POINTER_ERROR; src ROI
//     width < 1 or height < 1 -> NPP_SIZE_ERROR; nXFactor <= 0 or nYFactor <= 0
//     -> NPP_RESIZE_FACTOR_ERROR; eInterpolation outside
//     {NN, LINEAR, CUBIC, CUBIC2P_BSPLINE, CUBIC2P_CATMULLROM, CUBIC2P_B05C03,
//     SUPER, LANCZOS} -> NPP_INTERPOLATION_ERROR.  NPPI_INTER_LANCZOS3_ADVANCED
//     and the NPPI_SMOOTH_EDGE flag are rejected.
//   * result (round half away from zero, e.g. -3.5 -> -4, 3.5 -> 4):
//       x = round(oSrcROI.x * nXFactor + nXShift)
//       y = round(oSrcROI.y * nYFactor + nYShift)
//       width  = round(oSrcROI.width  * nXFactor)
//       height = round(oSrcROI.height * nYFactor)
//
// nppiGetResizeTiledSourceOffset(oSrcRectROI, oDstRectROI, pNewSrcRectOffset):
//   * validation order: any of the four rect width/height values < 1 ->
//     NPP_RESIZE_NO_OPERATION_ERROR; pNewSrcRectOffset == NULL ->
//     NPP_NULL_POINTER_ERROR (measured: the size check precedes the null check).
//   * the source rect offsets are ignored (a source at {99,99} behaves like
//     one at {0,0}); results truncate toward zero (0.75 -> 0, -0.75 -> 0,
//     -10.5 -> -10, 10.5 -> 10):
//       x = (int)(oDstRectROI.x * oSrcRectROI.width  / oDstRectROI.width)
//       y = (int)(oDstRectROI.y * oSrcRectROI.height / oDstRectROI.height)
//
// nppiResizeAdvancedGetBufferHostSize_8u_C1R(oSrcROI, oDstROI, hpBufferSize,
//                                            eInterpolationMode):
//   * eInterpolationMode != NPPI_INTER_LANCZOS3_ADVANCED (including the
//     NPPI_SMOOTH_EDGE flag) -> NPP_NOT_IMPLEMENTED_ERROR.
//   * no size validation at all; zero and negative sizes flow through the
//     arithmetic (NVIDIA returns -512 for a -16 wide destination).
//   * *hpBufferSize = 4 * oDstROI.width * oSrcROI.height bytes with 32-bit
//     wrap-around (NVIDIA returns 0 for 65536x65536 -> 65536x65536); the
//     intermediate is a 32-bit per pixel dstWidth x srcHeight horizontal pass.
//   * NVIDIA 13.4 dereferences a NULL hpBufferSize and crashes; mcMPP returns
//     NPP_NULL_POINTER_ERROR instead.  The path is not recordable and is not
//     covered by the differential suite.
//
// Device-side semantics (measured, see docs/npp_resize_semantics.md and the
// NppiResizeProbeDiff suite):
//   * SqrPixel coordinate: adjF = 1/f; adjS = shift*adjF + (1-adjF)*0.5;
//     srcX = fma(adjF, dstX, -adjS) with a single float32 rounding (double for
//     Npp64f).  There is no oDstROI offset in the mapping.
//   * nppiResize coordinate: adjF = oSrcROI.width / oDstROI.width and
//     srcX = oSrcROI.x + (dstX - oDstROI.x + 0.5) * adjF - 0.5.
//   * NPPI_INTER_NN rounds half up (floor(x + 0.5)); NPPI_INTER_LINEAR uses
//     floor/frac; NPPI_INTER_CUBIC is a 4-point *Lagrange* stencil
//     {x0-1, x0, x0+1, x0+2}; NPPI_INTER_LANCZOS is the standard 6-tap
//     Lanczos-3 (sinc(x)*sinc(x/3)); NPPI_INTER_SUPER is an area (box)
//     average with a source-space box of width 1/f starting at srcX-0.5.
//   * NPPI_INTER_CUBIC2P_BSPLINE / _CATMULLROM / _B05C03 are rejected with
//     NPP_INTERPOLATION_ERROR by every nppiResizeSqrPixel dtype (measured),
//     even though the header documentation lists them.
//   * destination pixels whose source coordinate is clipped by the source ROI
//     are not written.

#ifndef NPPI_RESIZE_EXECUTOR_H
#define NPPI_RESIZE_EXECUTOR_H

#include "npp.h"
#include "nppi_geometry_transforms.h"
#include <cuda_runtime.h>

namespace nppi {
namespace resize {

// ---- host helpers --------------------------------------------------------
inline int roundHalfAway(double value) { return (int)(value >= 0.0 ? value + 0.5 : value - 0.5); }

inline bool resizeRectInterpolationSupported(int eInterpolation) {
  switch (eInterpolation) {
    case NPPI_INTER_NN:
    case NPPI_INTER_LINEAR:
    case NPPI_INTER_CUBIC:
    case NPPI_INTER_CUBIC2P_BSPLINE:
    case NPPI_INTER_CUBIC2P_CATMULLROM:
    case NPPI_INTER_CUBIC2P_B05C03:
    case NPPI_INTER_SUPER:
    case NPPI_INTER_LANCZOS:
      return true;
    default:
      return false;
  }
}

inline NppStatus getResizeRect(NppiRect oSrcROI, NppiRect *pDstRect, double nXFactor, double nYFactor,
                               double nXShift, double nYShift, int eInterpolation) {
  // Measured order: the source-size check precedes the null-pointer check
  // (golden resize-host/getrect/error/null-over-size -> NPP_SIZE_ERROR).
  if (oSrcROI.width < 1 || oSrcROI.height < 1) {
    return NPP_SIZE_ERROR;
  }
  if (pDstRect == nullptr) {
    return NPP_NULL_POINTER_ERROR;
  }
  if (nXFactor <= 0.0 || nYFactor <= 0.0) {
    return NPP_RESIZE_FACTOR_ERROR;
  }
  if (!resizeRectInterpolationSupported(eInterpolation)) {
    return NPP_INTERPOLATION_ERROR;
  }
  pDstRect->x = roundHalfAway(oSrcROI.x * nXFactor + nXShift);
  pDstRect->y = roundHalfAway(oSrcROI.y * nYFactor + nYShift);
  pDstRect->width = roundHalfAway((double)oSrcROI.width * nXFactor);
  pDstRect->height = roundHalfAway((double)oSrcROI.height * nYFactor);
  return NPP_NO_ERROR;
}

inline NppStatus getResizeTiledSourceOffset(NppiRect oSrcRectROI, NppiRect oDstRectROI,
                                            NppiPoint *pNewSrcRectOffset) {
  if (oSrcRectROI.width < 1 || oSrcRectROI.height < 1 || oDstRectROI.width < 1 || oDstRectROI.height < 1) {
    return NPP_RESIZE_NO_OPERATION_ERROR;
  }
  if (pNewSrcRectOffset == nullptr) {
    return NPP_NULL_POINTER_ERROR;
  }
  pNewSrcRectOffset->x = (int)((double)oDstRectROI.x * oSrcRectROI.width / oDstRectROI.width);
  pNewSrcRectOffset->y = (int)((double)oDstRectROI.y * oSrcRectROI.height / oDstRectROI.height);
  return NPP_NO_ERROR;
}

inline NppStatus resizeAdvancedGetBufferHostSize(NppiSize oSrcROI, NppiSize oDstROI, int *hpBufferSize,
                                                 int eInterpolationMode) {
  if (hpBufferSize == nullptr) {
    return NPP_NULL_POINTER_ERROR;
  }
  if (eInterpolationMode != NPPI_INTER_LANCZOS3_ADVANCED) {
    return NPP_NOT_IMPLEMENTED_ERROR;
  }
  // Deliberate 32-bit wrap-around to match the NVIDIA arithmetic.
  *hpBufferSize = (int)(4u * (unsigned)oDstROI.width * (unsigned)oSrcROI.height);
  return NPP_NO_ERROR;
}

// ---- device entry points (defined in nppi_resize_kernel.cu) ---------------
// Packed / AC4 SqrPixel.
template <typename T, int C, bool AC4>
NppStatus sqrPixel(const T *pSrc, NppiSize oSrcSize, int nSrcStep, NppiRect oSrcROI, T *pDst, int nDstStep,
                   NppiRect oDstROI, double nXFactor, double nYFactor, double nXShift, double nYShift,
                   int eInterpolation, cudaStream_t stream);

// Planar SqrPixel (oPlanes == 3 or 4 independent planes).
template <typename T, int C>
NppStatus sqrPixelPlanar(const T *const pSrc[], int nSrcStep, NppiSize oSrcSize, NppiRect oSrcROI, T *const pDst[],
                         int nDstStep, NppiRect oDstROI, double nXFactor, double nYFactor, double nXShift,
                         double nYShift, int eInterpolation, cudaStream_t stream);

// Advanced SqrPixel (8u C1): pBuffer is validated, the Lanczos-3 kernel is
// applied in a single pass.
template <typename T, int C, bool AC4>
NppStatus sqrPixelAdvanced(const T *pSrc, NppiSize oSrcSize, int nSrcStep, NppiRect oSrcROI, T *pDst, int nDstStep,
                           NppiRect oDstROI, double nXFactor, double nYFactor, T *pBuffer, int eInterpolationMode,
                           cudaStream_t stream);

// Packed / AC4 nppiResize.
template <typename T, int C, bool AC4>
NppStatus resize(const T *pSrc, int nSrcStep, NppiSize oSrcSize, NppiRect oSrcROI, T *pDst, int nDstStep,
                 NppiSize oDstSize, NppiRect oDstROI, int eInterpolation, cudaStream_t stream);

// Planar nppiResize.
template <typename T, int C>
NppStatus resizePlanar(const T *const pSrc[], int nSrcStep, NppiSize oSrcSize, NppiRect oSrcROI, T *const pDst[],
                       int nDstStep, NppiSize oDstSize, NppiRect oDstROI, int eInterpolation, cudaStream_t stream);

// Batch entry points.
template <typename T, int C, bool AC4>
NppStatus resizeBatch(NppiSize oSmallestSrcSize, NppiRect oSrcROI, NppiSize oSmallestDstSize, NppiRect oDstROI,
                      int eInterpolation, NppiResizeBatchCXR *pBatchList, unsigned int nBatchSize,
                      cudaStream_t stream);

template <typename T, int C, bool AC4>
NppStatus resizeBatchAdvanced(int nMaxWidth, int nMaxHeight, NppiImageDescriptor *pBatchSrc,
                              NppiImageDescriptor *pBatchDst, NppiResizeBatchROI_Advanced *pBatchROI,
                              unsigned int nBatchSize, int eInterpolation, cudaStream_t stream);

}  // namespace resize
}  // namespace nppi

#endif  // NPPI_RESIZE_EXECUTOR_H
